// 这家店的商品可见性与生效价。
//
// price_source 取**最内的那一层**（有任何一个 SKU 用了门店价就是 3）：
// 它回答的是「这一行有没有被本地覆盖过」，运营要按它筛。一件商品的多个 SKU
// 落在不同层上是常态，取 max 而不是取第一个 —— 取第一个的话结果取决于
// SKU 的 id 顺序，而那是一个没人知道自己依赖了的东西。
//
// listed 为空（没有 override 行）即在售。region_listed 同理。
func (q *Queries) ScopedListStoreProducts(ctx context.Context, arg ScopedListStoreProductsParams) ([]ScopedListStoreProductsRow, error) {
	rows, err := q.db.Query(ctx, scopedListStoreProducts,
		arg.StoreID,
		arg.RegionID,
		arg.Listed,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ScopedListStoreProductsRow
	for rows.Next() {
		var i ScopedListStoreProductsRow
		if err := rows.Scan(
			&i.ProductID,
			&i.Title,
			&i.Status,
			&i.Listed,
			&i.EffectiveListed,
			&i.MinPriceCents,
			&i.MaxPriceCents,
			&i.PriceSource,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
